<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\Auth;use App\Services\SubscriptionEligibilityService;Auth::requirePermission('ELIGIBILITY_VIEW_ALL');$rows=SubscriptionEligibilityService::allEligibility();$pageTitle='Fleet Eligibility';require BASE_PATH.'/app/Views/layout/header.php';?><div class="page-head"><div><h1>Fleet eligibility</h1><p>Latest automatic resource assessment across Carriers.</p></div><span class="badge"><?=h(count(array_filter($rows,fn($r)=>$r['assessment_result']==='eligible')))?> available</span></div><div class="card table-wrap" tabindex="0" aria-label="Scrollable fleet eligibility table"><table style="min-width:1260px"><thead><tr><th>Carrier</th><th>Truck</th><th>Driver</th><th>Result</th><th>Availability</th><th>Reason</th><th>Assessed UTC</th></tr></thead><tbody><?php foreach($rows as$r):?><tr><td><?=h($r['carrier_company_name']?:$r['carrier_user_name'])?></td><td><?=h($r['registration_number'])?></td><td><?=h($r['driver_name']?:'Not linked')?></td><td><?=h($r['assessment_result'])?></td><td><?=h($r['availability_status'])?></td><td><?=h($r['reason'])?></td><td><?=h($r['assessed_at'])?></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="muted">No assessments.</td></tr><?php endif;?></tbody></table></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
